// ViolationReason classifies a refused frame. Only some reasons map to a wire error
// class.
type ViolationReason string

const (
	// ReasonFrameTooLarge reports that the encoded event or message exceeded its byte
	// bound. Detected on the raw bytes before deserialisation.
	ReasonFrameTooLarge ViolationReason = "frame_too_large"
	// ReasonMalformedJSON reports that the message was not well-formed JSON, or was
	// truncated.
	ReasonMalformedJSON ViolationReason = "malformed_json"
	// ReasonUnsupportedSchemaVersion reports that schema_version was absent, not an
	// integer, or not a version this build accepts.
	ReasonUnsupportedSchemaVersion ViolationReason = "unsupported_schema_version"
	// ReasonUnknownMessageType reports that type was absent or not an event type this
	// source owns. A consumer that receives an event type it does not know MUST ignore it
	// rather than fail; a producer that writes one through this codec is refused.
	ReasonUnknownMessageType ViolationReason = "unknown_message_type"
	// ReasonPayloadTooLarge reports that the payload exceeded the byte bound declared for
	// its event type.
	ReasonPayloadTooLarge ViolationReason = "payload_too_large"
	// ReasonSchemaViolation reports that the message parsed but did not satisfy the
	// schema for its type.
	ReasonSchemaViolation ViolationReason = "schema_violation"
)

// ViolationErrorClass maps a rejection reason to the connector error class reported
// for it.
var ViolationErrorClass = map[ViolationReason]ErrorClass{
	ReasonFrameTooLarge:            "",
	ReasonMalformedJSON:            "",
	ReasonUnsupportedSchemaVersion: ErrorClassUnsupportedCapability,
	ReasonUnknownMessageType:       ErrorClassUnsupportedCapability,
	ReasonPayloadTooLarge:          "",
	ReasonSchemaViolation:          ErrorClassValidationFailed,
}

