// Identifier is defined by the connector protocol schema.
//
// Opaque durable identifier (docs/DOMAIN_MODEL.md section 3). Consumers MUST treat the
// value as opaque: the schema bounds only its length and character class and never its
// documented prefix, and the value encodes no tenant, no timestamp and no database
// sequence.
type Identifier = string

// Timestamp is defined by the connector protocol schema.
//
// RFC 3339 timestamp in UTC, with a mandatory trailing Z.
type Timestamp = string

// SequenceNumber is defined by the connector protocol schema.
//
// Position in a project's event stream. Monotonically increasing within a project and
// never reused. Global ordering across projects is not guaranteed, and the value is
// not a database row identifier a consumer may depend on.
type SequenceNumber = int64

// Cursor is defined by the connector protocol schema.
//
// Opaque pagination cursor (docs/API.md section 6). It is base64url text without
// padding; its contents are the server's business and a client MUST NOT parse,
// construct or modify one.
type Cursor = string

// Slug is defined by the connector protocol schema.
//
// Human-friendly alias, unique inside its parent. Mutable, and never a substitute for
// the identifier (docs/DOMAIN_MODEL.md section 3).
type Slug = string

// DisplayName is defined by the connector protocol schema.
//
// Name a human reads. It is description and never an authorisation input.
type DisplayName = string

// EmailAddress is defined by the connector protocol schema.
//
// Address a human is known by. It is an alias for a user, never an identity: the
// identifier is what every other record references. The bound is the RFC 5321 maximum
// path length. The pattern is deliberately permissive — one at-sign, no whitespace and
// no control characters — because a stricter one rejects addresses that work: a
// dotless host such as administrator@localhost is what a fresh self-hosted
// installation is seeded with, and deliverability is not something a schema can
// decide.
type EmailAddress = string

// GitRefName is defined by the connector protocol schema.
//
// Git branch name. Bounded and restricted to the characters a ref may hold, so a value
// stored here cannot become an argument to something else.
type GitRefName = string

// RepositoryCanonical is defined by the connector protocol schema.
//
// The canonical member of a repository identity on its own, for the records that store
// the normalised form without the clone URLs beside it (docs/DOMAIN_MODEL.md section
// 9). Its shape is repository_identity.canonical, and the shared normaliser in
// packages/protocol produces both, so a workspace and a project cannot disagree about
// what one repository is.
type RepositoryCanonical = string

// EnvironmentLabel is defined by the connector protocol schema.
//
// Operator-assigned environment label. Its shape is the connector protocol's
// environment_label, because an enrolment token pins the labels a registering
// environment must declare (docs/CONNECTOR_PROTOCOL.md section 4.1).
type EnvironmentLabel = string

// PlatformName is defined by the connector protocol schema.
//
// Operating system an environment runs, as the connector reported it.
type PlatformName = string

// ArchitectureName is defined by the connector protocol schema.
//
// CPU architecture an environment runs, as the connector reported it.
type ArchitectureName = string

// ConnectorCapability is defined by the connector protocol schema.
//
// Capability a connector build advertises, such as http-tunnel, websocket-tunnel,
// git-context or local-mcp-bridge. Unknown values are accepted so that a newer
// connector is classified by docs/CONNECTOR_PROTOCOL.md section 19 rather than
// rejected outright.
type ConnectorCapability = string

// ConnectorVersion is defined by the connector protocol schema.
//
// Connector release version, for example 0.1.0. Its shape is the connector protocol's
// semantic_version.
type ConnectorVersion = string

// CertificateFingerprint is defined by the connector protocol schema.
//
// sha256:<hex> digest of the DER form of an issued connector certificate (ADR-0014).
// It is unique across connectors and is how a verified peer certificate is resolved to
// a connector record.
type CertificateFingerprint = string

// SilenceSeconds is defined by the connector protocol schema.
//
// A lower bound, in seconds, on how long a connector had been silent when a conclusion
// was drawn about it.
type SilenceSeconds = int64

// PathHash is defined by the connector protocol schema.
//
// Stable sha256:<hex> digest of a workspace's absolute path on the development
// machine. The control plane stores the digest rather than the path, because a display
// label and a stable local hash are sufficient to recognise the same checkout again
// (docs/DOMAIN_MODEL.md section 9).
type PathHash = string

// WorkspaceDisplayLabel is defined by the connector protocol schema.
//
// Human-readable workspace label, which is the checkout directory's own name and never
// its full path. Path separators and control characters are refused, so a full path
// cannot be smuggled through it.
type WorkspaceDisplayLabel = string

// GitCommit is defined by the connector protocol schema.
//
// A commit identifier, lowercase hexadecimal. Bounded so that an abbreviated and a
// full identifier are both accepted and nothing else is.
type GitCommit = string

// Sha256Digest is defined by the connector protocol schema.
//
// A SHA-256 digest in lower-case hexadecimal. It is the only checksum algorithm this
// version defines, so a reader never has to negotiate one.
type Sha256Digest = string

// ArchiveMemberPath is defined by the connector protocol schema.
//
// A path inside a backup archive, always relative and always forward-slashed. The
// character set excludes a leading slash and a backslash; a member whose path
// traverses upwards is refused by the reader rather than by this pattern, because a
// regular expression that has to be read as a security control is one nobody can
// check.
type ArchiveMemberPath = string

// PublicAlias is defined by the connector protocol schema.
//
// Leftmost label of a route's internal origin (docs/ARCHITECTURE.md section 7.3). It
// MUST be a DNS label and MUST be unique across the deployment, so the control plane
// generates it rather than deriving it from the route identifier, whose conventional
// svc_ prefix is not a valid label. Consumers MUST treat it as opaque.
type PublicAlias = string

// InternalOrigin is defined by the connector protocol schema.
//
// Origin an authorised browser session opens, of the form
// https://<public_alias>.<suffix>/. The control plane derives it from the alias; it is
// never taken from a request, because the origin is the browser session's egress
// allow-list (docs/SECURITY.md section 9).
type InternalOrigin = string

// LocalHost is defined by the connector protocol schema.
//
// Local address of the development service, as a literal IP address. A name would have
// to be resolved, and a resolver is a rebinding surface: the name that passed the
// destination policy need not be the address the connector later opens
// (docs/SECURITY.md section 9).
type LocalHost = string

// LocalPort is defined by the connector protocol schema.
//
// TCP port the development service listens on.
type LocalPort = int64

// ObservedDestination is defined by the connector protocol schema.
//
// The destination the connector reported it actually opened, as host:port
// (docs/CONNECTOR_PROTOCOL.md section 11). It is what the connector observed rather
// than what the control plane asked for, so that the two can be compared.
type ObservedDestination = string

// RepositoryIdentity is defined by the connector protocol schema.
//
// Provider-agnostic repository identity (docs/DOMAIN_MODEL.md section 6). canonical is
// the normalised host-and-path form that two clone URLs for the same repository both
// reduce to, which is what lets an SSH remote and an HTTPS remote be recognised as one
// repository. clone_urls records the forms actually seen, for display and for a
// connector to match a checkout against.
type RepositoryIdentity struct {
	// Normalised host and path, lowercase host, no scheme, no credentials, no .git suffix
	// and no trailing slash, for example github.com/example/refresh-surplus.
	Canonical string `json:"canonical"`
	// Clone URLs that reduce to canonical, in the order they were supplied. Duplicates
	// are removed by the control plane before storage.
	CloneURLs []string `json:"clone_urls,omitempty"`
}

// ValidationViewport is defined by the connector protocol schema.
//
// A viewport the project validates at (docs/UX_FLOWS.md section 4). The bounds are the
// browser protocol's, because a viewport stored here is one a browser session is later
// asked to adopt; a value the worker would refuse must not be storable.
type ValidationViewport struct {
	// Viewport width in CSS pixels.
	Width int64 `json:"width"`
	// Viewport height in CSS pixels.
	Height int64 `json:"height"`
	// Device pixel ratio. Absent means 1, which is what a browser session adopts when the
	// project does not say otherwise.
	DeviceScaleFactor *float64 `json:"device_scale_factor,omitempty"`
}

// ProjectSettings is defined by the connector protocol schema.
//
// Project settings (docs/DOMAIN_MODEL.md section 6). Stage 1 holds the default
// validation viewports and nothing else; the object refuses unknown members so a
// setting cannot be introduced in one service without being defined here first.
type ProjectSettings struct {
	// Viewports a finding is expected to be validated at. It defaults to 390x844 and
	// 1440x900, which AGENTS.md requires of browser-facing work and the Stage 1
	// completion gate checks against.
	DefaultValidationViewports []ValidationViewport `json:"default_validation_viewports"`
}

// Organisation is defined by the connector protocol schema.
//
// The top-level administrative and data-isolation boundary (docs/DOMAIN_MODEL.md
// section 4).
type Organisation struct {
	// Organisation identity, conventionally prefixed org_.
	ID string `json:"id"`
	// Display name.
	Name string `json:"name"`
	// Mutable alias.
	Slug string `json:"slug"`
	// Lifecycle status.
	Status OrganisationStatus `json:"status"`
	// When the organisation was created.
	CreatedAt string `json:"created_at"`
	// When it last changed.
	UpdatedAt string `json:"updated_at"`
}

// User is defined by the connector protocol schema.
//
// A human identity (docs/DOMAIN_MODEL.md section 5). It never carries credential
// material: whether a password exists is stated, and the hash is not part of any
// representation that leaves the database.
type User struct {
	// User identity, conventionally prefixed usr_.
	ID string `json:"id"`
	// Owning organisation, carried for defence-in-depth filtering (docs/DOMAIN_MODEL.md
	// section 3).
	OrganisationID string `json:"organisation_id"`
	// Address the human is known by.
	Email string `json:"email"`
	// Name shown in a timeline.
	DisplayName string `json:"display_name"`
	// Lifecycle status.
	Status UserStatus `json:"status"`
	// Whether this user can authenticate locally. It is the fact a first-run screen
	// needs, and it says nothing about the credential itself. The name avoids the word
	// the schema checker forbids in a field, which exists so that no protocol field can
	// ever carry a credential.
	LocalCredentialSet *bool `json:"local_credential_set,omitempty"`
	// When the user record was created.
	CreatedAt string `json:"created_at"`
	// When it last changed.
	UpdatedAt string `json:"updated_at"`
}

// Project is defined by the connector protocol schema.
//
// The principal working boundary (docs/DOMAIN_MODEL.md section 6). A review belongs to
// exactly one project, and a browser session may only route to services authorised for
// the same project.
type Project struct {
	// Project identity, conventionally prefixed prj_.
	ID string `json:"id"`
	// Owning organisation, carried for defence-in-depth filtering.
	OrganisationID string `json:"organisation_id"`
	// Display name.
	Name string `json:"name"`
	// Alias, unique within the organisation.
	Slug string `json:"slug"`
	// Repository the project's work lands in. Absent until an operator supplies one; a
	// change to it is audited as project.repository_changed.
	RepositoryIdentity *RepositoryIdentity `json:"repository_identity,omitempty"`
	// Branch reviews are captured against by default.
	DefaultBranch string `json:"default_branch"`
	// Lifecycle status. Deleting a project archives it.
	Status ProjectStatus `json:"status"`
	// Project settings.
	Settings ProjectSettings `json:"settings"`
	// Optimistic-concurrency version (docs/API.md section 5.2). A write carrying a
	// different expected_version is refused with VERSION_CONFLICT rather than silently
	// overwriting.
	Version int64 `json:"version"`
	// When the project was created.
	CreatedAt string `json:"created_at"`
	// When it last changed.
	UpdatedAt string `json:"updated_at"`
}

// HumanSession is defined by the connector protocol schema.
//
// What a human session tells its own holder (docs/API.md section 4). The session token
// lives in an HTTP-only cookie and is never part of this representation; project_ids
// absent means organisation-wide scope, and a list means exactly those projects.
type HumanSession struct {
	// Session identity, conventionally prefixed vwr_.
	SessionID string `json:"session_id"`
	// The authenticated user. Absent for a session issued from the bootstrap
	// administrator token, which has no user record behind it (ADR-0016).
	UserID *string `json:"user_id,omitempty"`
	// Organisation the session acts in.
	OrganisationID *string `json:"organisation_id,omitempty"`
	// Address of the authenticated user, when there is one.
	Email *string `json:"email,omitempty"`
	// Name shown in the application shell.
	Display string `json:"display"`
	// Projects the session may reach. Absent means every project in the organisation.
	ProjectIDs []string `json:"project_ids,omitempty"`
	// When the session stops being usable without revocation.
	ExpiresAt string `json:"expires_at"`
}

// AgentSession is defined by the connector protocol schema.
//
// A bounded agent execution context (docs/DOMAIN_MODEL.md section 11), as a human
// interface shows it. project_id is required because an agent session is bound to
// exactly one project and a half-resolved one is not representable (ADR-0020).
// capabilities is what the session was granted when it opened and not what its
// credential carries now, so a record of what an agent was allowed to do survives a
// later revocation. No member of this shape can carry a credential: the token is never
// part of a session representation.
type AgentSession struct {
	// Agent-session identity, conventionally prefixed ags_.
	ID string `json:"id"`
	// Owning organisation.
	OrganisationID *string `json:"organisation_id,omitempty"`
	// Project the session is bound to. Exactly one, always.
	ProjectID string `json:"project_id"`
	// Connector the session reached the control plane through, where it came through the
	// local bridge.
	ConnectorID *string `json:"connector_id,omitempty"`
	// Workspace the session resolved, where the project has one.
	WorkspaceID *string `json:"workspace_id,omitempty"`
	// Client's self-reported name. It is description and never an authorisation input:
	// the credential decides what the session may do.
	AgentType string `json:"agent_type"`
	// Client's self-reported version.
	AgentVersion *string `json:"agent_version,omitempty"`
	// Capabilities the session holds. It cannot exceed the set its credential carried
	// when it opened.
	Capabilities []AgentCapability `json:"capabilities"`
	// Branch the workspace was on when the session started.
	Branch *string `json:"branch,omitempty"`
	// Head commit at that moment.
	HeadCommit *string `json:"head_commit,omitempty"`
	// Session status.
	Status AgentSessionStatus `json:"status"`
	// When the session opened.
	StartedAt string `json:"started_at"`
	// When the control plane last handled a request from it.
	LastSeenAt *string `json:"last_seen_at,omitempty"`
	// When it ended, where it has.
	EndedAt *string `json:"ended_at,omitempty"`
}

// Environment is defined by the connector protocol schema.
//
// A registered development location such as a VM or workstation (docs/DOMAIN_MODEL.md
// section 7). An environment may host several workspaces, but every published service
// and session association is explicitly project scoped, so project_id is a default
// rather than the whole of the authorisation.
type Environment struct {
	// Environment identity, conventionally prefixed env_.
	ID string `json:"id"`
	// Owning organisation, carried for defence-in-depth filtering.
	OrganisationID string `json:"organisation_id"`
	// Project the environment was enrolled for. Absent when the enrolment token was
	// organisation scoped.
	ProjectID *string `json:"project_id,omitempty"`
	// Operator-visible environment name, as the connector reported it. It is description
	// and never an authorisation input.
	Name string `json:"name"`
	// Operating system the environment runs.
	Platform string `json:"platform"`
	// CPU architecture the environment runs.
	Architecture string `json:"architecture"`
	// Operator-assigned labels. An enrolment token may pin the labels a registering
	// environment must declare.
	Labels []string `json:"labels"`
	// Trust level. Stage 1 has one.
	TrustLevel EnvironmentTrustLevel `json:"trust_level"`
	// Lifecycle status.
	Status EnvironmentStatus `json:"status"`
	// When a connector for this environment was last heard from. Absent until one has
	// been.
	LastSeenAt *string `json:"last_seen_at,omitempty"`
	// When the environment was registered.
	CreatedAt string `json:"created_at"`
}

// Connector is defined by the connector protocol schema.
//
// A connector installation and its cryptographic identity (docs/DOMAIN_MODEL.md
// section 8). The device private key is generated on the development machine and never
// leaves it, so this record has no member capable of carrying one: it holds the
// certificate fingerprint the control plane resolves a verified peer certificate by,
// and nothing secret.
type Connector struct {
	// Connector identity, conventionally prefixed con_.
	ID string `json:"id"`
	// Owning organisation, carried for defence-in-depth filtering.
	OrganisationID string `json:"organisation_id"`
	// Environment this connector runs in.
	EnvironmentID string `json:"environment_id"`
	// Project the connector was enrolled for. Absent when the enrolment token was
	// organisation scoped.
	ProjectID *string `json:"project_id,omitempty"`
	// Fingerprint of the issued client certificate, unique across connectors.
	CertificateFingerprint string `json:"certificate_fingerprint"`
	// When the issued identity expires. Identities are bounded in time.
	CertificateNotAfter string `json:"certificate_not_after"`
	// Connector release the environment runs.
	Version string `json:"version"`
	// Capabilities the connector build advertises.
	Capabilities []string `json:"capabilities"`
	// Lifecycle status.
	Status ConnectorStatus `json:"status"`
	// When the connector most recently reached ACTIVE. Absent before its first channel.
	ConnectedAt *string `json:"connected_at,omitempty"`
	// When the last heartbeat arrived. Absent before the first one.
	LastHeartbeatAt *string `json:"last_heartbeat_at,omitempty"`
	// When the identity was revoked. Absent unless the connector is REVOKED.
	RevokedAt *string `json:"revoked_at,omitempty"`
	// When the identity was issued.
	CreatedAt string `json:"created_at"`
}

// Workspace is defined by the connector protocol schema.
//
// A repository checkout a connector reports or an operator registers
// (docs/DOMAIN_MODEL.md section 9). It holds a stable path hash and a display label
// rather than the checkout's full path, and it has no member capable of carrying
// source file contents or a changed-path list: what is reportable about somebody
// else's machine is bounded by this schema rather than by the code that fills it in.
type Workspace struct {
	// Workspace identity, conventionally prefixed wsp_.
	ID string `json:"id"`
	// Owning organisation, carried for defence-in-depth filtering.
	OrganisationID string `json:"organisation_id"`
	// Project the checkout belongs to.
	ProjectID string `json:"project_id"`
	// Environment holding the checkout. Absent for a workspace registered
	// administratively rather than observed by a connector.
	EnvironmentID *string `json:"environment_id,omitempty"`
	// Connector that last reported the checkout. Absent for an administratively
	// registered workspace.
	ConnectorID *string `json:"connector_id,omitempty"`
	// Stable digest of the checkout's absolute path.
	PathHash string `json:"path_hash"`
	// Label a human reads, which is the checkout directory's own name.
	DisplayPath string `json:"display_path"`
	// Canonical identity of the checkout's remote. Absent when the checkout has no remote
	// that could be normalised; an absent value is reported as absent rather than guessed
	// at.
	RepositoryIdentity *string `json:"repository_identity,omitempty"`
	// Checked-out branch.
	Branch string `json:"branch"`
	// HEAD commit.
	HeadCommit string `json:"head_commit"`
	// Whether the working tree has uncommitted changes. Which files changed is
	// deliberately not recorded.
	Dirty bool `json:"dirty"`
	// How the workspace came to be known.
	Source WorkspaceObservationSource `json:"source"`
	// When the control plane last received this state. Absent until a first observation.
	LastObservedAt *string `json:"last_observed_at,omitempty"`
	// When the workspace record was created.
	CreatedAt string `json:"created_at"`
}

// Actor is defined by the connector protocol schema.
//
// The principal an event is attributed to (docs/EVENTS.md section 2).
type Actor struct {
	// Principal kind. It is the authoritative part of an actor; display is not.
	Type ActorType `json:"type"`
	// Identifier of the principal, absent for a system actor that has none.
	ID *string `json:"id,omitempty"`
	// Human-readable label for a timeline. It is description and never an authorisation
	// input.
	Display *string `json:"display,omitempty"`
}

// Correlation is defined by the connector protocol schema.
//
// Correlation identifiers (docs/EVENTS.md section 2, docs/ARCHITECTURE.md section 15).
// Every member is an opaque identifier: correlation never carries a header, a body or
// a secret.
type Correlation struct {
	// The API request that caused the event, conventionally prefixed req_.
	RequestID *string `json:"request_id,omitempty"`
	// The event that caused this one, conventionally prefixed evt_.
	CausationEventID *string `json:"causation_event_id,omitempty"`
	// Connector, conventionally prefixed con_.
	ConnectorID *string `json:"connector_id,omitempty"`
	// Environment, conventionally prefixed env_.
	EnvironmentID *string `json:"environment_id,omitempty"`
	// Workspace, conventionally prefixed wsp_.
	WorkspaceID *string `json:"workspace_id,omitempty"`
	// Published service, conventionally prefixed svc_.
	PublishedServiceID *string `json:"published_service_id,omitempty"`
	// Agent session, conventionally prefixed ags_.
	AgentSessionID *string `json:"agent_session_id,omitempty"`
	// Browser session, conventionally prefixed brs_.
	BrowserSessionID *string `json:"browser_session_id,omitempty"`
	// Browser worker, conventionally prefixed wkr_.
	WorkerID *string `json:"worker_id,omitempty"`
	// Artefact, conventionally prefixed art_.
	ArtefactID *string `json:"artefact_id,omitempty"`
	// Review, conventionally prefixed rev_.
	ReviewID *string `json:"review_id,omitempty"`
	// Finding, conventionally prefixed fin_.
	FindingID *string `json:"finding_id,omitempty"`
	// Annotation, conventionally prefixed ann_.
	AnnotationID *string `json:"annotation_id,omitempty"`
	// Durable job, conventionally prefixed job_.
	JobID *string `json:"job_id,omitempty"`
}

// Envelope is defined by the connector protocol schema.
//
// The docs/EVENTS.md section 2 event envelope. Every event names the organisation it
// belongs to, its position in a stream, and the actor that caused it; the payload
// schema is selected by type. project_id is optional because an occurrence can precede
// any project association — a connector enrolment does — and every project-scoped read
// filters on it.
type Envelope struct {
	// Event identifier, conventionally prefixed evt_. Consumers deduplicate on it.
	ID string `json:"id"`
	// Envelope schema version. Stage 1 accepts 1 only; any other value is rejected rather
	// than best-effort parsed.
	SchemaVersion int64 `json:"schema_version"`
	// Monotonic position within the stream.
	Sequence int64 `json:"sequence"`
	// Event type. This codec owns the types in message_type; an event of another type is
	// decoded by the schema source that owns it.
	Type MessageType `json:"type"`
	// When the occurrence happened.
	OccurredAt string `json:"occurred_at"`
	// When the control plane committed the record.
	RecordedAt string `json:"recorded_at"`
	// Owning organisation, conventionally prefixed org_.
	OrganisationID string `json:"organisation_id"`
	// Owning project, conventionally prefixed prj_. Every project-scoped read of this
	// stream filters on it.
	ProjectID *string `json:"project_id,omitempty"`
	// Principal the occurrence is attributed to.
	Actor Actor `json:"actor"`
	// Correlation identifiers.
	Correlation *Correlation `json:"correlation,omitempty"`
}

// OrganisationCreatedPayload is defined by the connector protocol schema.
//
// Payload of organisation.created.
type OrganisationCreatedPayload struct {
	// Mutable human-friendly alias. The identifier is authoritative; this is not.
	Slug string `json:"slug"`
	// Display name.
	Name string `json:"name"`
}

// ProjectCreatedPayload is defined by the connector protocol schema.
//
// Payload of project.created.
type ProjectCreatedPayload struct {
	// Project-scoped alias. Mutable, and never a substitute for the identifier.
	Slug string `json:"slug"`
	// Display name.
	Name string `json:"name"`
	// Branch the project captures reviews against. Absent on a project created before the
	// field existed.
	DefaultBranch *string `json:"default_branch,omitempty"`
	// Normalised repository identity the project was created with, when one was supplied.
	// The canonical form alone: the clone URLs are queryable on the record and add
	// nothing an auditor needs.
	RepositoryCanonical *string `json:"repository_canonical,omitempty"`
}

// ProjectRepositoryChangedPayload is defined by the connector protocol schema.
//
// Payload of project.repository_changed. It carries both sides of the move, because a
// review captured before it was interpreted against the previous repository
// (docs/DOMAIN_MODEL.md section 6).
type ProjectRepositoryChangedPayload struct {
	// Normalised identity before the change. Absent when the project had no repository
	// association.
	PreviousCanonical *string `json:"previous_canonical,omitempty"`
	// Normalised identity after the change.
	NewCanonical string `json:"new_canonical"`
}

// UserInvitedPayload is defined by the connector protocol schema.
//
// Payload of user.invited. Issuing a credential-establishing token is a permission
// change, and docs/SECURITY.md section 16 requires an audit record for one. It never
// carries the token: a reader learns that a way in exists and when it closes, not what
// it is.
type UserInvitedPayload struct {
	// User the token establishes credentials for.
	UserID string `json:"user_id"`
	// Kind of token that was issued.
	Method LoginMethod `json:"method"`
	// When the token stops being usable, whether or not it was used.
	ExpiresAt string `json:"expires_at"`
}

// UserCredentialsSetPayload is defined by the connector protocol schema.
//
// Payload of user.credentials_set. Setting a password is a permission change and
// docs/SECURITY.md section 16 requires an audit record for one; the record names the
// user and the route the credential arrived by, and nothing else.
type UserCredentialsSetPayload struct {
	// User whose password changed.
	UserID string `json:"user_id"`
	// How the credential was established.
	Method LoginMethod `json:"method"`
}

// AuthenticationLoginSucceededPayload is defined by the connector protocol schema.
//
// Payload of authentication.login_succeeded.
type AuthenticationLoginSucceededPayload struct {
	// Session that was issued.
	SessionID string `json:"session_id"`
	// User that authenticated. Absent for the bootstrap-token exchange, which has no user
	// record behind it.
	UserID *string `json:"user_id,omitempty"`
	// How the human authenticated.
	Method LoginMethod `json:"method"`
}

// AuthenticationLoginFailedPayload is defined by the connector protocol schema.
//
// Payload of authentication.login_failed. It never carries the submitted credential,
// and never the identifier that was typed beside it: a password mistyped into an email
// field would otherwise be written to an append-only table (docs/SECURITY.md section
// 18).
type AuthenticationLoginFailedPayload struct {
	// Stable failure class.
	Reason LoginFailureReason `json:"reason"`
	// Route the attempt arrived by.
	Method LoginMethod `json:"method"`
	// User the attempt named, when it named one that exists. Absent for an unknown
	// address, which is what stops the audit trail confirming which addresses have
	// accounts.
	UserID *string `json:"user_id,omitempty"`
}

// SessionRevokedPayload is defined by the connector protocol schema.
//
// Payload of session.revoked.
type SessionRevokedPayload struct {
	// Session that was revoked.
	SessionID string `json:"session_id"`
	// User the session belonged to, when it belonged to one.
	UserID *string `json:"user_id,omitempty"`
	// Why it was revoked.
	Reason SessionRevocationReason `json:"reason"`
}

// ProjectUpdatedPayload is defined by the connector protocol schema.
//
// Payload of project.updated. It names the fields that changed rather than restating
// the record: current state is queryable, and the audit question is what moved.
type ProjectUpdatedPayload struct {
	// Attribute names that changed, in schema order.
	ChangedFields []string `json:"changed_fields"`
}

// ProjectArchivedPayload is defined by the connector protocol schema.
//
// Payload of project.archived. It carries previous and new state, which docs/EVENTS.md
// section 8 requires of a state change.
type ProjectArchivedPayload struct {
	// Status before the change.
	PreviousStatus ProjectStatus `json:"previous_status"`
	// Status after the change.
	NewStatus ProjectStatus `json:"new_status"`
}

// ConnectorEnrolledPayload is defined by the connector protocol schema.
//
// Payload of connector.enrolled. It records the identity that was issued and the
// environment it was issued to, and it never carries the enrolment token that was
// redeemed: an event is append-only, so a credential written into one cannot be taken
// out again (docs/EVENTS.md section 8).
type ConnectorEnrolledPayload struct {
	// Environment the identity was issued to.
	EnvironmentID string `json:"environment_id"`
	// Name the environment reported for itself. Description, never an authorisation
	// input.
	EnvironmentName string `json:"environment_name"`
	// Operating system the environment reported.
	Platform string `json:"platform"`
	// CPU architecture the environment reported.
	Architecture string `json:"architecture"`
	// Connector release that enrolled.
	ConnectorVersion string `json:"connector_version"`
	// Capabilities the connector build advertised.
	Capabilities []string `json:"capabilities"`
	// Fingerprint of the certificate that was issued.
	CertificateFingerprint string `json:"certificate_fingerprint"`
	// When the issued identity expires.
	IdentityExpiresAt string `json:"identity_expires_at"`
	// Identifier of the token that was redeemed. The identifier, never the token.
	EnrolmentTokenID *string `json:"enrolment_token_id,omitempty"`
	// Status the record entered, which is PENDING_ENROLMENT until the first authenticated
	// channel.
	NewStatus ConnectorStatus `json:"new_status"`
}

// ConnectorConnectedPayload is defined by the connector protocol schema.
//
// Payload of connector.connected. Both sides of the transition are named, so the audit
// trail states what moved rather than only where it landed, and the trigger is a
// closed vocabulary so no free text is needed.
type ConnectorConnectedPayload struct {
	// Status before the transition.
	PreviousStatus ConnectorStatus `json:"previous_status"`
	// Status after it, which is ACTIVE.
	NewStatus ConnectorStatus `json:"new_status"`
	// Whether a channel was established or a heartbeat arrived from a degraded state.
	Trigger ConnectorConnectedTrigger `json:"trigger"`
}

// ConnectorDegradedPayload is defined by the connector protocol schema.
//
// Payload of connector.degraded. Degradation is a conclusion drawn from silence, so
// the payload states how long the silence had lasted rather than what the connector
// said about itself.
type ConnectorDegradedPayload struct {
	// Status before the transition.
	PreviousStatus ConnectorStatus `json:"previous_status"`
	// Status after it, which is DEGRADED.
	NewStatus ConnectorStatus `json:"new_status"`
	// What caused it. Degradation has one cause: missed heartbeats.
	Trigger ConnectorDegradedTrigger `json:"trigger"`
	// Lower bound on the silence, because the sweep observes silence rather than
	// measuring it.
	SilentForSecondsAtLeast int64 `json:"silent_for_seconds_at_least"`
}

// ConnectorDisconnectedPayload is defined by the connector protocol schema.
//
// Payload of connector.disconnected. A closed channel and an exhausted heartbeat
// budget are different observations and are distinguished by trigger, so an operator
// can tell a clean stop from a network that went away.
type ConnectorDisconnectedPayload struct {
	// Status before the transition.
	PreviousStatus ConnectorStatus `json:"previous_status"`
	// Status after it, which is DISCONNECTED.
	NewStatus ConnectorStatus `json:"new_status"`
	// Whether the channel closed or the disconnect threshold was exceeded.
	Trigger ConnectorDisconnectedTrigger `json:"trigger"`
	// Lower bound on the silence. Present only for heartbeat_timeout: a closed channel is
	// observed rather than inferred.
	SilentForSecondsAtLeast *int64 `json:"silent_for_seconds_at_least,omitempty"`
}

// ConnectorRevokedPayload is defined by the connector protocol schema.
//
// Payload of connector.revoked. It records what revocation reached, because
// docs/CONNECTOR_PROTOCOL.md section 18 makes revocation six things at once and an
// auditor needs to see that all six happened.
type ConnectorRevokedPayload struct {
	// Status before revocation.
	PreviousStatus ConnectorStatus `json:"previous_status"`
	// Status after it, which is REVOKED.
	NewStatus ConnectorStatus `json:"new_status"`
	// How many published services the revocation closed.
	RoutesRevoked int64 `json:"routes_revoked"`
	// How many browser sessions were marked disconnected by it.
	SessionsDisconnected int64 `json:"sessions_disconnected"`
	// How many live connector channels were closed. Zero when the connector held none.
	ChannelsClosed *int64 `json:"channels_closed,omitempty"`
	// How many live agent credentials the connector had minted were revoked with it
	// (ADR-0023). Refusing the exchange closes only the next one, so this count is what
	// closed the ones already issued. Each also writes its own session.revoked with the
	// reason connector_revoked.
	AgentCredentialsRevoked *int64 `json:"agent_credentials_revoked,omitempty"`
}

// WorkspaceObservedPayload is defined by the connector protocol schema.
//
// Payload of workspace.observed. It carries exactly what docs/CONNECTOR_PROTOCOL.md
// section 9 permits a connector to report about a checkout, and has no member capable
// of carrying file contents, a changed-path list or a full filesystem path.
type WorkspaceObservedPayload struct {
	// Workspace that was observed.
	WorkspaceID string `json:"workspace_id"`
	// Environment holding it. Absent for an administratively registered workspace.
	EnvironmentID *string `json:"environment_id,omitempty"`
	// Stable digest of the checkout's absolute path.
	PathHash string `json:"path_hash"`
	// The checkout directory's own name.
	DisplayPath string `json:"display_path"`
	// Canonical identity of the checkout's remote, when it has one that could be
	// normalised.
	RepositoryIdentity *string `json:"repository_identity,omitempty"`
	// Checked-out branch.
	Branch string `json:"branch"`
	// HEAD commit.
	HeadCommit string `json:"head_commit"`
	// Whether the working tree had uncommitted changes.
	Dirty bool `json:"dirty"`
	// How the workspace came to be known.
	Source WorkspaceObservationSource `json:"source"`
}

// WorkspaceHeadChangedPayload is defined by the connector protocol schema.
//
// Payload of workspace.head_changed. It carries both sides of the move, because a
// review captured before it was captured against the previous head and an auditor
// reading only the new one could not tell.
type WorkspaceHeadChangedPayload struct {
	// Workspace whose head moved.
	WorkspaceID string `json:"workspace_id"`
	// Environment holding it, when a connector reported the change.
	EnvironmentID *string `json:"environment_id,omitempty"`
	// Branch before the change.
	PreviousBranch string `json:"previous_branch"`
	// HEAD commit before it.
	PreviousHeadCommit string `json:"previous_head_commit"`
	// Dirty state before it.
	PreviousDirty bool `json:"previous_dirty"`
	// Branch after it.
	Branch string `json:"branch"`
	// HEAD commit after it.
	HeadCommit string `json:"head_commit"`
	// Dirty state after it.
	Dirty bool `json:"dirty"`
}

// JobEnqueuedPayload is defined by the connector protocol schema.
//
// Payload of job.enqueued.
type JobEnqueuedPayload struct {
	// Job identity, conventionally prefixed job_.
	JobID string `json:"job_id"`
	// Work the job performs.
	Kind JobKind `json:"kind"`
	// Earliest time the runner may claim it.
	RunAfter string `json:"run_after"`
}

// JobSucceededPayload is defined by the connector protocol schema.
//
// Payload of job.succeeded.
type JobSucceededPayload struct {
	// Job identity.
	JobID string `json:"job_id"`
	// Work the job performed.
	Kind JobKind `json:"kind"`
	// Attempts made, including the one that succeeded.
	Attempts int64 `json:"attempts"`
	// Wall-clock duration of the successful attempt.
	DurationMs int64 `json:"duration_ms"`
}

// JobFailedPayload is defined by the connector protocol schema.
//
// Payload of job.failed.
type JobFailedPayload struct {
	// Job identity.
	JobID string `json:"job_id"`
	// Work the job attempted.
	Kind JobKind `json:"kind"`
	// Attempts made, including the one that failed.
	Attempts int64 `json:"attempts"`
	// Stable failure class.
	Reason JobFailureReason `json:"reason"`
	// Whether another attempt is scheduled. Stated rather than inferred, so an operator
	// can tell a retry from a dead job without reading the runner's source.
	Retrying bool `json:"retrying"`
	// When the next attempt becomes claimable. Absent when no attempt will follow.
	NextAttemptAt *string `json:"next_attempt_at,omitempty"`
}

// BackupProduct is defined by the connector protocol schema.
//
// The build that produced the archive (docs/DEPLOYMENT.md section 16). Recorded so a
// restore can state which release wrote the data it is about to load.
type BackupProduct struct {
	// Product version the image reports.
	Version string `json:"version"`
	// Source revision the image was built from, or unknown when the build did not stamp
	// one.
	Revision string `json:"revision"`
	// Build time the image reports, or unknown. It is a free string rather than a
	// timestamp because an unstamped development build has no build time and inventing
	// one would be a lie in an audit record.
	BuiltAt string `json:"built_at"`
}

// BackupSource is defined by the connector protocol schema.
//
// Where the archive came from. hostname is what makes a restore to a new host visible:
// a restore that changes it says so and states which credentials it invalidated
// (docs/DEPLOYMENT.md section 17).
type BackupSource struct {
	// The gateway hostname the installation was serving, when it was configured. Absent
	// when the deployment terminates TLS in front of the stack and the control plane was
	// never told a hostname.
	Hostname *string `json:"hostname,omitempty"`
	// Artefact store the installation was running.
	ArtefactDriver BackupArtefactDriver `json:"artefact_driver"`
}

// BackupTable is defined by the connector protocol schema.
//
// One backed-up table and the number of rows the archive carries for it. The count is
// what a restore compares its own result against, so a load that silently dropped rows
// fails rather than reporting success.
type BackupTable struct {
	// Table name in the public schema.
	Name string `json:"name"`
	// Rows written for this table.
	Rows int64 `json:"rows"`
}

// BackupEntry is defined by the connector protocol schema.
//
// One member of the archive, with the digest and size the manifest binds it to. Every
// member but the manifest itself appears here, so a member that was truncated, altered
// or omitted is detected before anything is written.
type BackupEntry struct {
	// Path of the member inside the archive.
	Path string `json:"path"`
	// Uncompressed size of the member.
	Bytes int64 `json:"bytes"`
	// Digest of the member's bytes.
	Sha256 string `json:"sha256"`
}

// BackupKeyMaterial is defined by the connector protocol schema.
//
// Whether the archive carries key material, and which tables were held back when it
// does not (docs/SECURITY.md section 20). It is stated in every archive rather than
// only in the archives that carry it, because absence has to be a recorded fact for a
// restore to be able to say what it cannot reconstruct.
type BackupKeyMaterial struct {
	// True only when the operator explicitly opted in. A portable backup carrying key
	// material is a private key in a file an operator will copy somewhere, so it is never
	// the default.
	Included bool `json:"included"`
	// Tables whose rows were held back because they hold key material. Empty when key
	// material was included.
	ExcludedTables []string `json:"excluded_tables"`
}

// BackupManifest is defined by the connector protocol schema.
//
// The manifest of a backup archive (docs/DEPLOYMENT.md section 16). It is the first
// member of the archive, so a reader learns what it holds before reading anything
// else, and it is the single structure both the backup writer and the restore reader
// validate against.
type BackupManifest struct {
	// Manifest structure version. A reader refuses a version it does not know rather than
	// guessing at the members it recognises.
	ManifestVersion int64 `json:"manifest_version"`
	// When the archive was written.
	CreatedAt string `json:"created_at"`
	// What the archive carries.
	Mode BackupMode `json:"mode"`
	// Build that produced the archive.
	Product BackupProduct `json:"product"`
	// Migration file at the head of the backed-up schema, which is the schema version
	// reviewplane migrate reports. A restore refuses an archive whose schema is ahead of
	// the installed build, because the rows would name columns this build's migrations
	// have not created.
	SchemaVersion string `json:"schema_version"`
	// Installation the archive came from.
	Source BackupSource `json:"source"`
	// Every table in the public schema, with the rows the archive carries. Tables are
	// enumerated from the live catalogue rather than from a list in the source, so a
	// table added by a later migration is backed up without anyone remembering to add it
	// here.
	Tables []BackupTable `json:"tables"`
	// Artefact objects carried. Zero in database mode, and zero in full mode only when
	// the store held none.
	ArtefactObjects int64 `json:"artefact_objects"`
	// Total uncompressed size of the artefact objects carried.
	ArtefactBytes int64 `json:"artefact_bytes"`
	// Storage keys that artefact metadata referenced and the store did not hold at backup
	// time. Recorded rather than silently skipped: application metadata is authoritative
	// for availability (ADR-0012), so a row without bytes is missing evidence and a
	// restore has to be able to report it.
	ArtefactsMissing []string `json:"artefacts_missing,omitempty"`
	// Key-material disposition.
	KeyMaterial BackupKeyMaterial `json:"key_material"`
	// Distinct encryption key references the backed-up data names (docs/SECURITY.md
	// section 15). A reference is a name for a key held elsewhere and never key material,
	// so recording it is what lets a restore state which keys the restored installation
	// will need. Empty while envelope encryption is unimplemented.
	KeyReferences []string `json:"key_references"`
	// Whether a configuration member was written. It carries the non-secret settings of
	// the installation and records a secret only as the name of the variable that held
	// it.
	ConfigurationIncluded *bool `json:"configuration_included,omitempty"`
	// Algorithm every digest in this manifest uses.
	ChecksumAlgorithm BackupManifestChecksumAlgorithm `json:"checksum_algorithm"`
	// Every archive member but the manifest, with its digest. The manifest cannot carry
	// its own digest, so whole-archive integrity is the digest the backup command prints
	// and records in its audit event; these entries are what detect a truncated or
	// corrupted member.
	Entries []BackupEntry `json:"entries"`
}

// MigrationRecord is defined by the connector protocol schema.
//
// One migration and what it says about being undone.
type MigrationRecord struct {
	// Migration file name, which is also its position in the apply order.
	Filename string `json:"filename"`
	// Downgrade support the migration declares.
	Downgrade MigrationDowngrade `json:"downgrade"`
	// The reason the migration gives, when it gives one.
	Note *string `json:"note,omitempty"`
}

// MigrationState is defined by the connector protocol schema.
//
// What a database has applied and what it has not (docs/DEPLOYMENT.md section 11). It
// is the shape reviewplane migrate --status reports and the shape the upgrade
// preflight reads, so an operator and a script are answering the same question from
// the same structure.
type MigrationState struct {
	// Highest applied migration. Absent for a database nobody has migrated, which is a
	// state rather than an error.
	SchemaVersion *string `json:"schema_version,omitempty"`
	// Migrations this database has applied, in apply order.
	Applied []MigrationRecord `json:"applied"`
	// Migrations on disk this database has not applied, in apply order.
	Pending []MigrationRecord `json:"pending"`
}

// CompatibilityCheck is defined by the connector protocol schema.
//
// One preflight check and what it found.
type CompatibilityCheck struct {
	// Which check this is.
	Name CompatibilityCheckName `json:"name"`
	// What it found.
	Status CompatibilityStatus `json:"status"`
	// One line an operator can act on. It never carries a connection string, a credential
	// or a network address (docs/SECURITY.md section 18): preflight output is pasted into
	// issues.
	Detail string `json:"detail"`
}

// CompatibilityReport is defined by the connector protocol schema.
//
// The upgrade preflight report (docs/OPERATIONS.md section 12, docs/DEPLOYMENT.md
// section 15 step 5).
type CompatibilityReport struct {
	// True only when no check failed. A warning does not clear it to false, and a check
	// that could not run reports fail rather than being omitted.
	Ok bool `json:"ok"`
	// When the preflight ran.
	CheckedAt string `json:"checked_at"`
	// Every check, in a stable order, including the ones that passed.
	Checks []CompatibilityCheck `json:"checks"`
}

// StreamSubscribe is defined by the connector protocol schema.
//
// Subscription request (docs/API.md section 18.1).
type StreamSubscribe struct {
	// Message discriminator.
	Type StreamSubscribeType `json:"type"`
	// The highest project sequence the client has already applied. Zero means the client
	// holds nothing and wants the stream from its start; a client that has just loaded
	// current state sends the sequence that state was read at.
	LastSequence int64 `json:"last_sequence"`
	// Largest replay the client will accept. A gap larger than this is answered with a
	// refresh instruction rather than a long replay, which is cheaper for both sides than
	// paging through history the client is about to refetch anyway.
	MaxReplay *int64 `json:"max_replay,omitempty"`
}

// StreamSubscribed is defined by the connector protocol schema.
//
// Subscription accepted.
type StreamSubscribed struct {
	// Message discriminator.
	Type StreamSubscribedType `json:"type"`
	// Project the stream belongs to.
	ProjectID string `json:"project_id"`
	// Sequence the stream is at now. Zero when the project has no events yet.
	CurrentSequence int64 `json:"current_sequence"`
	// Oldest sequence still replayable. A client below it receives a refresh instruction
	// instead of a replay.
	EarliestAvailableSequence int64 `json:"earliest_available_sequence"`
	// Whether events between the client's position and current_sequence follow before
	// live delivery begins.
	Replaying bool `json:"replaying"`
}

// StreamRefreshRequired is defined by the connector protocol schema.
//
// The client's position cannot be served from the retained stream (docs/EVENTS.md
// section 10).
type StreamRefreshRequired struct {
	// Message discriminator.
	Type StreamRefreshRequiredType `json:"type"`
	// Why a replay was not possible.
	Reason StreamRefreshRequiredReason `json:"reason"`
	// Sequence the stream is at now. A client refetches state and resumes from it.
	CurrentSequence int64 `json:"current_sequence"`
	// Oldest sequence still replayable.
	EarliestAvailableSequence int64 `json:"earliest_available_sequence"`
}

// StreamHeartbeat is defined by the connector protocol schema.
//
// Liveness on a quiet stream.
type StreamHeartbeat struct {
	// Message discriminator.
	Type StreamHeartbeatType `json:"type"`
	// Sequence the stream is at now.
	CurrentSequence int64 `json:"current_sequence"`
	// When the control plane sent the heartbeat.
	SentAt string `json:"sent_at"`
}

// StreamError is defined by the connector protocol schema.
//
// A refusal on an open subscription.
type StreamError struct {
	// Message discriminator.
	Type StreamErrorType `json:"type"`
	// Stable error code.
	Code ErrorClass `json:"code"`
	// Human-readable explanation. It never carries request data, a credential or a stack
	// trace.
	Message string `json:"message"`
	// Whether repeating the subscription verbatim can succeed. Stated rather than
	// inferred from the code, because the answer is not derivable from the code's shape.
	Retryable bool `json:"retryable"`
}

// ApiErrorDetails is defined by the connector protocol schema.
//
// Code-specific refusal detail (docs/MCP_SPEC.md section 12). Every member is optional
// and the object refuses unknown members, so the detail a caller may rely on is a
// fixed vocabulary rather than whatever a handler happened to attach.
type ApiErrorDetails struct {
	// The version the record actually holds. Carried by VERSION_CONFLICT so a caller can
	// re-read and retry rather than guess.
	CurrentVersion *int64 `json:"current_version,omitempty"`
	// The version the caller supplied. Carried beside current_version so a log line
	// records both halves of the conflict without the caller having to quote its own
	// request back.
	ExpectedVersion *int64 `json:"expected_version,omitempty"`
	// The control epoch that is current. Carried by CONTROL_EPOCH_STALE.
	CurrentEpoch *int64 `json:"current_epoch,omitempty"`
	// Identifiers the caller may name to resolve the ambiguity. Carried by
	// PROJECT_CONTEXT_AMBIGUOUS.
	Candidates []string `json:"candidates,omitempty"`
	// Transitions that are legal from the record's current state. Carried by a refused
	// transition.
	AllowedTransitions []string `json:"allowed_transitions,omitempty"`
	// Evidence the operation needs before it can succeed. Carried by EVIDENCE_REQUIRED.
	RequiredEvidence []string `json:"required_evidence,omitempty"`
	// Captured context the request omitted. Carried by a refusal to store a finding that
	// could not be reproduced later.
	MissingContext []string `json:"missing_context,omitempty"`
	// How long to wait before repeating the request. Carried by RATE_LIMITED and by a
	// duplicate that arrived while the first call was still in flight.
	RetryAfterMs *int64 `json:"retry_after_ms,omitempty"`
	// The request member the refusal is about.
	Field *string `json:"field,omitempty"`
	// Stable sub-reason where one code covers several causes.
	Reason *string `json:"reason,omitempty"`
}

// ApiError is defined by the connector protocol schema.
//
// The refusal itself (docs/API.md section 5).
type ApiError struct {
	// Stable machine-readable code.
	Code ErrorClass `json:"code"`
	// Human-readable explanation. It never carries a credential, request data or a stack
	// trace (docs/SECURITY.md section 18).
	Message string `json:"message"`
	// Code-specific detail.
	Details *ApiErrorDetails `json:"details,omitempty"`
}

// ApiMeta is defined by the connector protocol schema.
//
// Response metadata carried by every API response (docs/API.md sections 5 and 6).
type ApiMeta struct {
	// Correlation identifier for this request, conventionally prefixed req_. It appears
	// on success and on refusal, so a caller can quote one identifier when reporting
	// either.
	RequestID string `json:"request_id"`
	// Cursor for the next page. Absent on the last page and on a response that is not a
	// collection.
	NextCursor *string `json:"next_cursor,omitempty"`
}

// ApiErrorResponse is defined by the connector protocol schema.
//
// The complete refusal body (docs/API.md section 5). A success body is {"data": ...,
// "meta": ...} whose data is endpoint-specific and therefore defined by the endpoint's
// own schema; meta is api_meta in both cases.
type ApiErrorResponse struct {
	// The refusal.
	Error ApiError `json:"error"`
	// Response metadata.
	Meta ApiMeta `json:"meta"`
}

// CursorClaims is defined by the connector protocol schema.
//
// What an opaque pagination cursor encodes. It is defined here so both languages
// encode and decode the same bytes, and never to invite a client to build one: the
// encoded form is base64url text and the API refuses a cursor whose shape it did not
// produce.
type CursorClaims struct {
	// Cursor format version. A cursor of another version is refused rather than guessed
	// at.
	Version int64 `json:"version"`
	// Value of the collection's sort column at the last row of the previous page.
	SortKey string `json:"sort_key"`
	// Identifier of the last row of the previous page, which breaks ties when the sort
	// column repeats.
	ID string `json:"id"`
}

// PublishedService is defined by the connector protocol schema.
//
// A temporary route from an authorised browser worker to a local development service
// (docs/DOMAIN_MODEL.md section 10). It has no member capable of carrying a capability
// token: a capability is a bearer credential the control plane mints and never stores,
// and this record names only the sessions one may be minted for.
type PublishedService struct {
	// Published-service identity, conventionally prefixed svc_.
	ID string `json:"id"`
	// Owning organisation, carried for defence-in-depth filtering.
	OrganisationID string `json:"organisation_id"`
	// Project the route belongs to. A capability issued for this project is refused
	// anywhere else.
	ProjectID string `json:"project_id"`
	// Connector that carries the route.
	ConnectorID string `json:"connector_id"`
	// Workspace the development service was started from.
	WorkspaceID string `json:"workspace_id"`
	// Leftmost label of the internal origin.
	PublicAlias string `json:"public_alias"`
	// Origin an authorised browser session opens.
	InternalOrigin string `json:"internal_origin"`
	// Local address the connector opens. The default is loopback.
	LocalHost string `json:"local_host"`
	// Local port the connector opens.
	LocalPort int64 `json:"local_port"`
	// Protocol declared at publication.
	Protocol DestinationProtocol `json:"protocol"`
	// What the route is scoped to.
	Scope PublishedServiceScope `json:"scope"`
	// Browser sessions a route authorises. At least one is required: a route no session
	// may use is not published (docs/CONNECTOR_PROTOCOL.md section 11).
	AllowedBrowserSessionIDs []string `json:"allowed_browser_session_ids"`
	// When the route expires. Publication always expires, and no stream's deadline may
	// exceed this instant.
	ExpiresAt string `json:"expires_at"`
	// Lifecycle status.
	Status PublishedServiceStatus `json:"status"`
	// Why the publication was refused. Present only when the status is failed.
	FailureClass *PublishedServiceFailureClass `json:"failure_class,omitempty"`
	// Destination the connector reported it opened. Absent until the route is ready.
	ObservedDestination *string `json:"observed_destination,omitempty"`
	// When publication was requested.
	RequestedAt string `json:"requested_at"`
	// When the route began carrying traffic. Absent until it does.
	ReadyAt *string `json:"ready_at,omitempty"`
	// When the route stopped carrying traffic, by failure, expiry or revocation. Absent
	// while it is live.
	EndedAt *string `json:"ended_at,omitempty"`
}

// PublishedServiceRequestedPayload is defined by the connector protocol schema.
//
// Payload of published_service.requested. It is written before anything is sent to the
// connector or the gateway, so the audit trail records the destination that was asked
// for even when the publication is then refused.
type PublishedServiceRequestedPayload struct {
	// Route requested.
	PublishedServiceID string `json:"published_service_id"`
	// Connector asked to carry it.
	ConnectorID string `json:"connector_id"`
	// Workspace the service was started from.
	WorkspaceID string `json:"workspace_id"`
	// Destination address requested.
	LocalHost string `json:"local_host"`
	// Destination port requested.
	LocalPort int64 `json:"local_port"`
	// Destination protocol declared.
	Protocol DestinationProtocol `json:"protocol"`
	// Alias the internal origin was built from.
	PublicAlias string `json:"public_alias"`
	// When the requested route expires.
	ExpiresAt string `json:"expires_at"`
	// Browser sessions a route authorises. At least one is required: a route no session
	// may use is not published (docs/CONNECTOR_PROTOCOL.md section 11).
	AllowedBrowserSessionIDs []string `json:"allowed_browser_session_ids"`
	// Status the record was written in, which is requested.
	NewStatus PublishedServiceStatus `json:"new_status"`
}

// PublishedServiceReadyPayload is defined by the connector protocol schema.
//
// Payload of published_service.ready. It is written for two occurrences: a route that
// began carrying traffic, and a session-scoped capability minted against one. Neither
// carries the capability token, only its identifier, because an event is append-only
// and a credential written into one cannot be taken out again (docs/EVENTS.md section
// 8).
type PublishedServiceReadyPayload struct {
	// Route concerned.
	PublishedServiceID string `json:"published_service_id"`
	// Status before the move. Absent when the event records a capability mint, which
	// moves no status.
	PreviousStatus *PublishedServiceStatus `json:"previous_status,omitempty"`
	// Status after the move. Absent on a capability mint.
	NewStatus *PublishedServiceStatus `json:"new_status,omitempty"`
	// Destination the connector reported it opened.
	ObservedDestination *string `json:"observed_destination,omitempty"`
	// Origin the gateway registered for the route.
	InternalOrigin *string `json:"internal_origin,omitempty"`
	// Whether the gateway held the connector's data channel when it registered the route.
	ConnectorConnected *bool `json:"connector_connected,omitempty"`
	// Capability minted, when this event records a mint. The token itself never appears.
	CapabilityID *string `json:"capability_id,omitempty"`
	// Session the capability was minted for.
	BrowserSessionID *string `json:"browser_session_id,omitempty"`
	// Signing key the capability was minted with, so that a rotation can be audited.
	KeyID *string `json:"key_id,omitempty"`
	// When the minted capability expires. It never outlives its route.
	ExpiresAt *string `json:"expires_at,omitempty"`
}

// PublishedServiceFailedPayload is defined by the connector protocol schema.
//
// Payload of published_service.failed. The class is the diagnosis: docs/API.md section
// 10 requires one failure to carry one code from the connector to the caller, so what
// refused the publication is recorded under the name the caller was given.
type PublishedServiceFailedPayload struct {
	// Route refused.
	PublishedServiceID string `json:"published_service_id"`
	// Status before the refusal.
	PreviousStatus PublishedServiceStatus `json:"previous_status"`
	// Status after it, which is failed.
	NewStatus PublishedServiceStatus `json:"new_status"`
	// Stable class that refused it.
	ErrorClass PublishedServiceFailureClass `json:"error_class"`
}

// PublishedServiceExpiredPayload is defined by the connector protocol schema.
//
// Payload of published_service.expired. Expiry is the ordinary end of a route, and it
// closes streams that are already in flight, including an upgraded one
// (docs/ARCHITECTURE.md section 7.3).
type PublishedServiceExpiredPayload struct {
	// Route that expired.
	PublishedServiceID string `json:"published_service_id"`
	// Status before expiry.
	PreviousStatus PublishedServiceStatus `json:"previous_status"`
	// Status after it, which is expired.
	NewStatus PublishedServiceStatus `json:"new_status"`
	// The expiry the sweep enforced.
	ExpiresAt string `json:"expires_at"`
}

// PublishedServiceRevokedPayload is defined by the connector protocol schema.
//
// Payload of published_service.revoked. Revocation is idempotent and writes this once.
// It names the capabilities it withdrew, because revoking a route without withdrawing
// the credentials minted against it would leave the revocation partial.
type PublishedServiceRevokedPayload struct {
	// Route revoked.
	PublishedServiceID string `json:"published_service_id"`
	// Status before revocation.
	PreviousStatus PublishedServiceStatus `json:"previous_status"`
	// Status after it, which is revoked.
	NewStatus PublishedServiceStatus `json:"new_status"`
	// Capabilities withdrawn with the route. Identifiers only: a token never appears in
	// an event.
	RevokedCapabilityIDs []string `json:"revoked_capability_ids,omitempty"`
}

// Payload is implemented by every version 1 message payload. The interface is closed:
// only payloads generated from the schema can satisfy it.
type Payload interface {
	// MessageType reports the envelope type this payload belongs to.
	MessageType() MessageType
	isConnectorPayload()
}

